const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const { createRequire } = require('node:module');
const ts = require('typescript');

const parserPath = path.resolve('src/lib/import/framing-plan/parse.ts');
const original = fs.readFileSync(parserPath, 'utf8');
const sha256 = text => crypto.createHash('sha256').update(text).digest('hex');
const ast = ts.createSourceFile(parserPath, original, ts.ScriptTarget.Latest, true);
const edits = [];
const hooks = { text: 0, remember: 0, grid: 0 };
function wrap(node, call, args) {
  edits.push({ start: node.getStart(ast), end: node.end,
    text: `${call}(${node.getText(ast)}, ${args})` });
}
function visit(node, owner) {
  if (ts.isFunctionDeclaration(node)) owner = node.name?.text;
  if (owner === 'collectTokens' && ts.isCallExpression(node) &&
      node.expression.getText(ast) === 'dimensions.push') {
    assert.equal(node.arguments.length, 1);
    wrap(node.arguments[0], '__text', 'normalizedText');
    hooks.text++;
  }
  if (owner === 'validateSequence' && ts.isReturnStatement(node) &&
      node.expression && ts.isObjectLiteralExpression(node.expression) &&
      node.expression.properties.some(p => p.name?.getText(ast) === 'spansMm')) {
    const spans = node.expression.properties.find(p => p.name?.getText(ast) === 'spansMm');
    const expression = spans.initializer.getText(ast);
    const partial = expression.startsWith('solution.spans');
    const tokens = partial ? 'solution.spans.slice(first.firstIndex, first.lastIndex)' :
      expression.startsWith('selected.solution.spans') ? 'selected.solution.spans' : 'selected.spans';
    wrap(node.expression, '__remember', `${tokens}, dimensions, sequence, ${partial ? 'first.firstIndex' : '0'}`);
    hooks.remember++;
  }
  if (owner === 'gridCandidate' && ts.isReturnStatement(node) && node.expression) {
    wrap(node.expression, '__grid', 'sequence');
    hooks.grid++;
  }
  ts.forEachChild(node, child => visit(child, owner));
}
visit(ast);
assert.deepEqual(hooks, { text: 1, remember: 3, grid: 1 });
let instrumented = original;
for (const edit of edits.sort((a, b) => b.start - a.start)) {
  instrumented = instrumented.slice(0, edit.start) + edit.text + instrumented.slice(edit.end);
}
const tokenText = new WeakMap();
const selectedBySpans = new WeakMap();
const gridOrigins = new WeakMap();
function loadParser(code) {
  const js = ts.transpileModule(code, { compilerOptions: {
    target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.CommonJS,
  }}).outputText;
  const module = { exports: {} };
  new Function('require', 'module', 'exports', '__text', '__remember', '__grid', js)(
    createRequire(parserPath), module, module.exports,
    (token, text) => { tokenText.set(token, text); return token; },
    (result, tokens, dimensions, sequence, start) => {
      selectedBySpans.set(result.spansMm, { tokens, dimensions, sequence, start });
      return result;
    },
    (grid, sequence) => { gridOrigins.set(grid, sequence); return grid; },
  );
  return module.exports.parseFramingPlan;
}
const baseline = loadParser(original);
const measured = loadParser(instrumented);
const fixtureDir = 'tests/fixtures/section-import/textitems';
const files = fs.readdirSync(fixtureDir).filter(file => file.endsWith('.json')).sort();
assert.equal(files.length, 36);
const windowPt = Number(original.match(/const DIMENSION_WINDOW_PT = ([0-9.]+)/)[1]);
const tolerancePt = Number(original.match(/const MIDPOINT_TOLERANCE_PT = ([0-9.]+)/)[1]);
const pages = [];
const allSpans = [];
for (const file of files) {
  const fixturePath = `${fixtureDir}/${file}`;
  const fixtureBytes = fs.readFileSync(fixturePath);
  const fixture = JSON.parse(fixtureBytes.toString('utf8'));
  const input = { ...fixture.page, items: fixture.items };
  const beforeInput = JSON.stringify(input);
  const plainOutput = baseline(input);
  const output = measured(input);
  assert.deepEqual(output, plainOutput, `Instrumentation changed ${file}`);
  assert.equal(JSON.stringify(input), beforeInput, `Input mutated: ${file}`);
  const returned = [...output.grids, ...output.blocks.flatMap(b => [b.xGrid, b.yGrid])];
  const unique = new Set(returned.map(grid => {
    const sequence = gridOrigins.get(grid);
    assert.ok(sequence, `Untraced grid: ${file}`);
    return sequence;
  }));
  const spans = [];
  for (const sequence of unique) {
    const observation = selectedBySpans.get(sequence.spansMm);
    assert.ok(observation, `Untraced selection: ${file}`);
    const { tokens, dimensions, sequence: originalSequence, start } = observation;
    assert.equal(tokens.length, sequence.axes.length - 1);
    const along = sequence.alongKey;
    const across = along === 'x' ? 'y' : 'x';
    const used = new Set(tokens);
    tokens.forEach((token, i) => {
      assert.equal(token.valueMm, sequence.spansMm[i]);
      const positions = [sequence.axes[i].positionPt, sequence.axes[i + 1].positionPt];
      const midpoint = (positions[0] + positions[1]) / 2;
      const bands = [...new Set([
        ...originalSequence.axisAcrossOptions[start + i],
        ...originalSequence.axisAcrossOptions[start + i + 1],
      ])];
      assert.ok(bands.some(band => Math.abs(token[across] - band) <= windowPt));
      const distance = Math.abs(token[along] - midpoint);
      assert.ok(distance <= tolerancePt);
      const competitors = dimensions.filter(candidate => !used.has(candidate) &&
        bands.some(band => Math.abs(candidate[across] - band) <= windowPt))
        .sort((a, b) => Math.abs(a[along] - midpoint) - Math.abs(b[along] - midpoint));
      const competitor = competitors[0];
      const row = {
        page: file.replace(/\.json$/, ''), direction: sequence.direction,
        axis_labels: [sequence.axes[i].label, sequence.axes[i + 1].label],
        dimension_text: tokenText.get(token), value_mm: token.valueMm,
        value_pt: distance, along_key: along, positions_pt: positions,
        midpoint_pt: midpoint, token_center_pt: { x: token.x, y: token.y },
        bands_pt: bands, total_confirmed: sequence.totalConfirmed,
        competitor: competitor ? {
          dimension_text: tokenText.get(competitor), value_mm: competitor.valueMm,
          value_pt: Math.abs(competitor[along] - midpoint),
        } : null,
      };
      spans.push(row);
      allSpans.push(row);
    });
  }
  pages.push({ path: fixturePath, sha256: sha256(fixtureBytes),
    grids: output.grids.length, blocks: output.blocks.length,
    returned_sequences: unique.size, span_count: spans.length,
    instrumented_output_equals_baseline: true,
    output_sha256: sha256(JSON.stringify(output)), spans });
}
const max = allSpans.reduce((a, b) => a.value_pt >= b.value_pt ? a : b);
const minB = allSpans.filter(s => s.competitor).reduce((a, b) =>
  a.competitor.value_pt <= b.competitor.value_pt ? a : b);
const minUnconfirmed = allSpans.filter(s => !s.total_confirmed && s.competitor)
  .reduce((a, b) => a.competitor.value_pt <= b.competitor.value_pt ? a : b);
assert.equal(fs.readFileSync(parserPath, 'utf8'), original);
const result = {
  parser_sha256: sha256(original), hooks, tolerance_pt: tolerancePt,
  dimension_window_pt: windowPt,
  remeasured: { page_count: pages.length, span_count: allSpans.length,
    A: { value_pt: max.value_pt, page: max.page, direction: max.direction,
      axis_labels: max.axis_labels, dimension_text: max.dimension_text } },
  accepted_max: max, B: minB, unconfirmed_B: minUnconfirmed,
  grid_count: pages.reduce((sum, p) => sum + p.grids, 0),
  block_count: pages.reduce((sum, p) => sum + p.blocks, 0),
  parser_file_unchanged: true, pages,
};
fs.writeFileSync('.cache/phase43-step0-measurement.json', JSON.stringify(result, null, 2) + '\n');
console.log(JSON.stringify({ ...result.remeasured, accepted_max: max,
  B: minB.competitor.value_pt, unconfirmed_B: minUnconfirmed.competitor.value_pt,
  grids: result.grid_count, blocks: result.block_count }));
